/* Lot 101: the scroll and view timeline lists and the scroll timeline time (generated by scripts/lot101_colorgen.py; expectations from scripts/lot101_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[256];
static wf_csstl_t g_t[8];

static const char *show(int n) {
    int k, m;
    if (n < 0) return "-1";
    m = snprintf(g_o, sizeof(g_o), "%d:", n);
    for (k = 0; k < n && m < (int)sizeof(g_o); k++)
        m += snprintf(g_o + m, sizeof(g_o) - (size_t)m, " %s/%d", g_t[k].name[0] ? g_t[k].name : "-", g_t[k].axis);
    return g_o;
}

/* wf_csstl_parse; items past the count stay untouched (all of them may
 * be written for an invalid list) */
static const char *tp(int which, const char *v, int max) {
    int n, k;
    memset(g_t, 0x5a, sizeof(g_t));
    n = wf_csstl_parse(which, v, g_t, max);
    for (k = n < 0 ? 8 : n; k < 8; k++) if (g_t[k].axis != 0x5a) return "WRITTEN";
    return show(n);
}

static const char *tc(const char *names, const char *axes) { return show(wf_csstl_coord(names, axes, g_t, 4)); }

/* wf_csstl_text of the shorthand list v (names or axes) */
static const char *tx(const char *v, int axes, int cap) {
    static char t[256];
    int n = wf_csstl_parse(WF_CSSTL_SHORT, v, g_t, 4), r;
    memset(t, 'q', sizeof(t));
    r = wf_csstl_text(g_t, n, axes, t, cap);
    if (r != (int)strlen(t)) return "BAD LENGTH";
    snprintf(g_o, sizeof(g_o), "%d %s", r, t);
    return g_o;
}

static const char *sm(int dur, int delay, int iters, int prog) {
    wf_cssanim_t a;
    int ms = -7, r;
    memset(&a, 0, sizeof(a));
    a.dur = dur; a.delay = delay; a.iters = iters;
    r = wf_cssanim_scroll_ms(&a, prog, &ms);
    snprintf(g_o, sizeof(g_o), "%d %d", r, ms);
    return g_o;
}

static void test_l101_tl_0(void) {
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "inline, , --t", 3));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "--scroller,", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "x y , --u block , --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy y", 3));
    TEST_ASSERT_EQUAL_STRING("1: --t/0", tp(WF_CSSTL_NAMES, "--t", 2));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "none,--t,--scroller,--u,--t", 4));
    TEST_ASSERT_EQUAL_STRING("1: -/2", tp(WF_CSSTL_AXES, "x", 8));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "x", 0));
    TEST_ASSERT_EQUAL_STRING("2: --u/0 --a-b/0", tp(WF_CSSTL_NAMES, "--u,--a-b", 3));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "--scroller inline , --x1 y , --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy inline , --t y , --a-b", 1));
    TEST_ASSERT_EQUAL_STRING("1: -/0", tp(WF_CSSTL_AXES, "block", 2));
    TEST_ASSERT_EQUAL_STRING("1: --v/0", tp(WF_CSSTL_NAMES, "--v", 8));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "block,x,y", 1));
}

static void test_l101_tl_1(void) {
    TEST_ASSERT_EQUAL_STRING("1: --a-b/0", tp(WF_CSSTL_NAMES, "--a-b", 8));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "--u", 0));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "block, block, y, horizontal, y", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "--zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz block,--a-b block", 0));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "--scroller inline , --a-b , none y , --v", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "auto, --u, --t --u, --a-b, --t", 0));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "block, 0, block", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "block --t, --v, --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy, --v block, --u", 2));
    TEST_ASSERT_EQUAL_STRING("4: --a-b/0 -/0 --a-b/0 -/0", tp(WF_CSSTL_NAMES, "--a-b,none,--a-b,none", 4));
    TEST_ASSERT_EQUAL_STRING("1: -/3", tp(WF_CSSTL_AXES, "y", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "--u,--t,auto,--t", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "--a-b,--a-b,--u,none", 3));
}

static void test_l101_tl_2(void) {
    TEST_ASSERT_EQUAL_STRING("2: -/2 -/1", tp(WF_CSSTL_AXES, "x, inline", 8));
    TEST_ASSERT_EQUAL_STRING("4: --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy/0 --t/0 --scroller/0 --t/0", tp(WF_CSSTL_NAMES, "--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy , --t , --scroller , --t", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "--v y,inline --t,--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy inline,--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy,--yyyyyyyyyyyyyyyyyyyyyyyyyyyyy", 8));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "--scroller, --yyyyyyyyyyyyyyyyyyyyyyyyyyyyy, none, --x1", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_NAMES, "", 3));
    TEST_ASSERT_EQUAL_STRING("3: --t/0 --a-b/0 --u/0", tp(WF_CSSTL_NAMES, "--t, --a-b, --u", 3));
    TEST_ASSERT_EQUAL_STRING("3: --v/2 --v/3 --v/2", tp(WF_CSSTL_SHORT, "--v x , --v y , --v x", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_AXES, "y,--t,y", 8));
    TEST_ASSERT_EQUAL_STRING("1: --u/0", tp(WF_CSSTL_SHORT, "--u", 4));
    TEST_ASSERT_EQUAL_STRING("2: --v/2 --u/2", tp(WF_CSSTL_SHORT, "--v x , --u x", 4));
    TEST_ASSERT_EQUAL_STRING("3: -/0 -/0 -/3", tp(WF_CSSTL_AXES, "block,block,y", 4));
    TEST_ASSERT_EQUAL_STRING("-1", tp(WF_CSSTL_SHORT, "--x1,--u,--v x,--t y", 3));
}

